import { analyzeBoneMarkers } from "./analyzeBoneMarkers.js";
import { analyzeTrends } from "./analyzeTrends.js";
import { analyzeContext } from "./analyzeContext.js";

/**
 * Combine independently calculated observations. No diagnosis, BMD estimate,
 * clinical risk score, or medical treatment is generated by this module.
 * Accepts arrays so it remains independent of Express and the mock API.
 */
export function analyzeBoneHealth({ astronautId, readings = [], symptoms = [], exercise = [] }) {
  if (typeof astronautId !== "string" || !astronautId.trim()) {
    throw new TypeError("astronautId is required");
  }

  const boneMarkers = analyzeBoneMarkers(readings, astronautId);
  const biomarkerTrends = analyzeTrends(readings, astronautId);
  const context = analyzeContext(symptoms, exercise, astronautId);

  const metricLabels = {
    serum_ctx: "Serum CTX",
    serum_p1np: "Serum P1NP",
    urine_calcium_24h: "24-hour urinary calcium"
  };

  const observations = [];
  const dataQualityFlags = [];
  const missingData = [];

  for (const [metric, label] of Object.entries(metricLabels)) {
    const comparison = boneMarkers.metrics[metric];
    const trend = biomarkerTrends.metrics[metric];
    if (comparison?.status === "analyzed") {
      const direction = comparison.trend === "unchanged" ? "was unchanged" : `${comparison.trend === "increasing" ? "increased" : "decreased"}`;
      observations.push(`${label} ${direction} by ${Math.abs(comparison.changePercent)}% compared with preflight baseline`);
    } else {
      missingData.push(`${metric}: ${comparison?.status ?? "missing"}`);
    }

    if (trend?.status !== "analyzed") {
      dataQualityFlags.push(`${metric} trend: ${trend?.reason ?? trend?.status ?? "missing"}`);
    } else if (trend.samplingGaps.length) {
      dataQualityFlags.push(`${metric}: ${trend.samplingGaps.length} sampling gap(s) exceed the expected interval`);
    }
  }

  if (context.symptoms.latest) {
    observations.push(`Reported back pain: ${context.symptoms.latest.backPainSeverity}/10 on mission day ${context.symptoms.latest.missionDay}`);
    if (context.symptoms.latest.postureChange) observations.push("A posture change was reported");
  } else {
    missingData.push("symptoms: no valid reports");
  }

  if (context.exercise.adherencePercent !== null) {
    observations.push(`Recorded exercise-minute adherence: ${context.exercise.adherencePercent}%`);
  } else {
    missingData.push("exercise: no valid logs");
  }
  if (context.symptoms.invalidRecordCount) {
    dataQualityFlags.push(`${context.symptoms.invalidRecordCount} invalid symptom report(s)`);
  }
  if (context.exercise.invalidRecordCount) {
    dataQualityFlags.push(`${context.exercise.invalidRecordCount} invalid exercise log(s)`);
  }

  const records = [...readings, ...symptoms, ...exercise].filter(
    r => r.astronautId === astronautId
  );
  const sourceValues = [...new Set(records.map(r => r.source ?? "unknown"))];
  const dataSource = sourceValues.length === 0 ? "none"
    : sourceValues.length === 1 ? sourceValues[0]
    : "mixed";
  const days = records.map(r => r.missionDay).filter(Number.isInteger);

  return {
    astronautId,
    analysisType: "bone_health_multimodal",
    latestMissionDay: days.length ? Math.max(...days) : null,
    dataSource,
    boneMarkers,
    biomarkerTrends,
    context,
    assessment: {
      status: "descriptive_only",
      observations,
      dataQualityFlags,
      missingData,
      measuredSpinalBmdChangePercent: null,
      predictedSpinalBmd: null,
      clinicalRisk: "not_assessed",
      medicalRecommendations: [],
      note: "These markers do not directly measure spinal bone density or establish an individual clinical risk. Review collection conditions and follow crew medical protocols."
    }
  };
}
